#!/usr/bin/env Rscript
options(warn=2);args<-commandArgs(trailingOnly=TRUE);if(length(args)!=2L)stop("usage: run_mv17d2_localization_qualification.R <prefreeze> <output>");p<-normalizePath(args[[1]],mustWork=TRUE);o<-args[[2]];if(dir.exists(o))stop("MV17-D2 output exists");dir.create(o,recursive=TRUE)
source("R/mv08z_landscape_production.R");source("R/mv17_h2_fixtures.R");source("R/mv17_localization.R");source("R/mv17_localization_horton.R");r<-.mv08z_read_csv;w<-.mv08z_atomic_csv;f<-r(file.path(p,"mv17d2-fixtures.csv"));c<-r(file.path(p,"mv17d2-contract.csv"))
make<-function(name,n,seed){if(name%in%c("circle","noisy_circle")){a<-seq(0,2*pi,length.out=n+1)[-1];x<-cbind(cos(a),sin(a));if(name=="noisy_circle"){set.seed(seed);x<-x+matrix(rnorm(n*2,0,.03),n,2)}}else if(name=="double_loop"){m<-n/2;a<-seq(0,2*pi,length.out=m+1)[-1];x<-rbind(cbind(cos(a)-c$double_loop_center_offset,sin(a)),cbind(cos(a)+c$double_loop_center_offset,sin(a)))}else{set.seed(seed);x<-matrix(rnorm(n*2),n,2)};rownames(x)<-sprintf("%s_p%03d",name,seq_len(n));x}
geometry<-function(name,x,cycle){if(!nrow(cycle))return(c(localized=FALSE,octants=0,radial_rmse=Inf));idx<-attr(cycle,"support_index");z<-x[idx,,drop=FALSE];centers<-if(name=="double_loop")c(-c$double_loop_center_offset,c$double_loop_center_offset)else 0;rmse<-vapply(centers,function(cx)sqrt(mean((sqrt((z[,1]-cx)^2+z[,2]^2)-1)^2)),numeric(1));cx<-centers[[which.min(rmse)]];angles<-(atan2(z[,2],z[,1]-cx)+2*pi)%%(2*pi);octants<-length(unique(floor(angles/(pi/4))));c(localized=min(rmse)<=c$maximum_radial_rmse&&octants>=c$minimum_angular_octants,octants=octants,radial_rmse=min(rmse))}
rows<-list();for(i in seq_len(nrow(f))){x<-make(f$fixture[i],f$points[i],f$seed[i]);dia<-as.data.frame(ripserr::vietoris_rips(x,max_dim=1L,threshold=Inf));h0<-mv17e_finite_intervals_v1(dia,0L);mst<-mv17d_h0_mergers_v1(x);h1<-mv17e_finite_intervals_v1(dia,1L);pers<-if(nrow(h1))h1$death-h1$birth else numeric();best<-if(length(pers))which.max(pers)else NA_integer_;maxp<-if(length(pers))max(pers)else 0;scale<-if(length(pers))(h1$birth[best]+h1$death[best])/2 else NA_real_;cycles<-list(if(is.finite(scale))mv17d_h1_cycle_v1(x,scale,"fundamental")else data.frame(),if(is.finite(scale))mv17d2_horton_cycle_v1(x,scale)else data.frame());geo<-lapply(cycles,function(z)geometry(f$fixture[i],x,z));set.seed(17299L);perm<-sample(seq_len(nrow(x)));cycles_perm<-list(if(is.finite(scale))mv17d_h1_cycle_v1(x[perm,,drop=FALSE],scale,"fundamental")else data.frame(),if(is.finite(scale))mv17d2_horton_cycle_v1(x[perm,,drop=FALSE],scale)else data.frame());rows[[i]]<-data.frame(fixture=f$fixture[i],points=nrow(x),finite_H0=nrow(h0),H0_MST_edges=nrow(mst),H0_max_death_error=if(nrow(h0)==nrow(mst))max(abs(sort(h0$death)-sort(mst$death)))else Inf,finite_H1=nrow(h1),maximum_H1_persistence=maxp,scale=scale,fundamental_found=nrow(cycles[[1]])==1L,horton_found=nrow(cycles[[2]])==1L,fundamental_localized=as.logical(geo[[1]][["localized"]]),horton_localized=as.logical(geo[[2]][["localized"]]),fundamental_octants=as.integer(geo[[1]][["octants"]]),horton_octants=as.integer(geo[[2]][["octants"]]),fundamental_radial_rmse=as.numeric(geo[[1]][["radial_rmse"]]),horton_radial_rmse=as.numeric(geo[[2]][["radial_rmse"]]),fundamental_support_sha256=if(nrow(cycles[[1]]))cycles[[1]]$support_sha256 else NA,horton_support_sha256=if(nrow(cycles[[2]]))cycles[[2]]$support_sha256 else NA,row_order_invariant=all(vapply(seq_along(cycles),function(k)nrow(cycles[[k]])==nrow(cycles_perm[[k]])&&(nrow(cycles[[k]])==0L||cycles[[k]]$support_sha256==cycles_perm[[k]]$support_sha256),logical(1))))}
w(do.call(rbind,rows),file.path(o,"mv17d2-summary.csv"));w(data.frame(contract_id="mv17d2_status_v1",fixtures=4L,workers=1L,retries=0L,real_localization_jobs=0L,labels_opened=FALSE,outcomes_opened=FALSE),file.path(o,"mv17d2-status.csv"))
